// ============ 核心缩放计算 ============
const calculateScale = () => {
    const screenWidth = window.innerWidth
    const screenHeight = window.innerHeight
    const designWidth = 1440
    const designHeight = 900
    
    // 边距：横屏留更多边距，竖屏留少一点
    const margin = isLandscape.value ? 30 : 15
    const usableWidth = Math.max(screenWidth - margin * 2, 100)
    const usableHeight = Math.max(screenHeight - margin * 2, 100)
    
    // 计算宽高各自的缩放比
    const scaleX = usableWidth / designWidth
    const scaleY = usableHeight / designHeight
    
    // 取最小值保证完全显示（类似 CSS object-fit: contain）
    let targetScale = Math.min(scaleX, scaleY)
    
    // 限制范围：最小 0.35，最大 1.2
    return Math.max(0.30, Math.min(1.1, targetScale))
};

// ============ 应用缩放 ============
const applyScale = () => {
  const newScale = calculateScale();
  scaleValue.value = newScale;
  console.log(`📐 缩放比例: ${newScale.toFixed(3)}, 方向: ${isLandscape.value ? '横屏' : '竖屏'}`);
};

